45	import org.springframework.samples.petclinic.util.AddressNormalizer;
46	import org.springframework.samples.petclinic.util.HouseholdNormalizer;
47	import org.springframework.samples.petclinic.util.TelephoneNormalizer;
48	import org.springframework.security.access.prepost.PreAuthorize;
49	import org.springframework.web.bind.annotation.CrossOrigin;
50	import org.springframework.web.bind.annotation.RequestMapping;
51	import org.springframework.web.bind.annotation.RestController;
52	import org.springframework.web.util.UriComponentsBuilder;
53	
54	import jakarta.transaction.Transactional;
55	
56	/**
57	 * @author Vitaliy Fedoriv
58	 */
59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    /** Maximum number of owners a single city may contain; creating an owner in a city that
66	     *  already has this many owners is rejected with 409 Conflict. */
67	    private static final int MAX_OWNERS_PER_CITY = 50;
68	
69	    /** Maximum number of owners that may be created on a single day (by registration date); creating
70	     *  an owner once this many owners already carry today's registration date is rejected with
71	     *  429 Too Many Requests. */
72	    private static final int MAX_OWNERS_PER_DAY = 100;
73	
74	    /** When more than this many owners already carry today's registration date at creation time, the
75	     *  new owner's 'bulkSignupWarning' flag is set true; otherwise it is false. */
76	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
77	
78	    /** Dedicated audit logger; a line is emitted here for each successful owner create. */
79	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
80	
81	    private final ClinicService clinicService;
82	
83	    private final OwnerMapper ownerMapper;
84	
85	    private final PetMapper petMapper;
86	
87	    private final VisitMapper visitMapper;
88	
89	    private final TelephoneNormalizer telephoneNormalizer;
90	
91	    private final HouseholdNormalizer householdNormalizer;
92	
93	    private final AddressNormalizer addressNormalizer;
94	
95	    public OwnerRestControllerV1(ClinicService clinicService,
96	                                 OwnerMapper ownerMapper,
97	                                 PetMapper petMapper,
98	                                 VisitMapper visitMapper,
99	                                 TelephoneNormalizer telephoneNormalizer,
100	                                 HouseholdNormalizer householdNormalizer,
101	                                 AddressNormalizer addressNormalizer) {
102	        this.clinicService = clinicService;
103	        this.ownerMapper = ownerMapper;
104	        this.petMapper = petMapper;
105	        this.visitMapper = visitMapper;
106	        this.telephoneNormalizer = telephoneNormalizer;
107	        this.householdNormalizer = householdNormalizer;
108	        this.addressNormalizer = addressNormalizer;
109	    }
110	
111	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
112	    @Override
113	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
114	        Collection<Owner> owners;
115	        if (lastName != null) {
116	            owners = this.clinicService.findOwnerByLastName(lastName);
117	        } else {
118	            owners = this.clinicService.findAllOwners();
119	        }
120	        if (owners.isEmpty()) {
121	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
122	        }
123	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
129	        Owner owner = this.clinicService.findOwnerById(ownerId);
130	        if (owner == null) {
131	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
132	        }
133	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Override
138	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
139	        HttpHeaders headers = new HttpHeaders();
140	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
141	        normalizeOwnerFields(owner);
142	        // Enforce the pre-persistence policies that can reject the new owner outright.
143	        rejectDisallowedOwnerCreation(owner);
144	        // Identify any existing owners who share a household (same last name and address,
145	        // compared case-insensitively with collapsed whitespace) with the owner being created.
146	        List<Owner> householdMembers = sameHouseholdOwners(owner.getLastName(), owner.getAddress());
147	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
148	        // Reject creating an owner who shares a household with an existing owner, unless the
149	        // request explicitly opts in with 'sharesHousehold' true.
150	        if (!sharesHousehold && !householdMembers.isEmpty()) {
151	            throw new DuplicateHouseholdException(
152	                "An owner with the same last name and address already exists");
153	        }
154	        // When opting in and joining an existing household, assign the new owner and every
155	        // existing member the same stable household identifier derived from the last name and
156	        // address, so all owners of the household share one 'householdId'.
157	        if (sharesHousehold && !householdMembers.isEmpty()) {
158	            String householdId = householdNormalizer.householdId(owner.getLastName(), owner.getAddress());
159	            owner.setHouseholdId(householdId);
160	            for (Owner member : householdMembers) {
161	                if (!householdId.equals(member.getHouseholdId())) {
162	                    member.setHouseholdId(householdId);
163	                    this.clinicService.saveOwner(member);
164	                }
165	            }
166	        }
167	        // Record how many existing owners already share this owner's first and last name
168	        // (compared case-insensitively) before this create, fixed at creation time.
169	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
170	        // Assign the customer code '<CITY3>-<LAST3>-<NNNN>' from the city, last name and a
171	        // per-city sequence equal to one more than the owners already in that city, fixed at
172	        // creation time.
173	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
174	        // Assign the membership number '<customerCode>-M<YY>', where YY is the last two digits
175	        // of the registration date's year (e.g. 'LON-SMI-0007-M26'), fixed at creation time.
176	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
177	        // Flag the create when more than 80 owners have already been created on this owner's
178	        // (adjusted business-day) registration date, fixed at creation time.
179	        owner.setBulkSignupWarning(
180	            countOwnersRegisteredOn(owner.getRegistrationDate()) > BULK_SIGNUP_WARNING_THRESHOLD);
181	        this.clinicService.saveOwner(owner);
182	        // Emit an audit line for the successful create, carrying the owner id, customer code and
183	        // registration date so the create can be traced from the dedicated AUDIT log.
184	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
185	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
186	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
187	        headers.setLocation(UriComponentsBuilder.newInstance()
188	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
189	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
190	    }
191	
192	    /**
193	     * Enforces the pre-persistence policies that reject a newly mapped and normalized owner
194	     * outright, in order, before any derived fields are assigned or the owner is saved. An owner
195	     * in a city that already contains {@link #MAX_OWNERS_PER_CITY} owners is rejected with 409
196	     * ({@link CityCapacityExceededException}), and an owner whose normalized telephone is already
197	     * used by another owner is rejected with 409 ({@link DuplicateTelephoneException}). Grouping the
198	     * independent create-time rejection rules here keeps {@link #addOwner} focused on the household,
199	     * derived-field and persistence steps. The household rule stays in {@link #addOwner} itself
200	     * because it shares the matched-member lookup with the shared household-id assignment.
201	     *
202	     * @param owner the newly mapped and normalized owner being created
203	     */
204	    private void rejectDisallowedOwnerCreation(Owner owner) {
205	        // Reject creating an owner once 100 or more owners already carry this owner's adjusted
206	        // business-day registration date.
207	        if (countOwnersRegisteredOn(owner.getRegistrationDate()) >= MAX_OWNERS_PER_DAY) {
208	            throw new DailyOwnerLimitExceededException(
209	                "The maximum number of owners that may be created today has already been reached");
210	        }
211	        // Reject creating an owner when the owner's city already contains 50 or more owners.
212	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
213	            throw new CityCapacityExceededException(
214	                "The city " + owner.getCity() + " already contains the maximum number of owners");
215	        }
216	        // Reject creating an owner whose normalized telephone is already used by another owner.
217	        String normalizedTelephone = owner.getTelephone();
218	        if (isTelephoneInUse(normalizedTelephone)) {
219	            throw new DuplicateTelephoneException(
220	                "An owner with telephone " + normalizedTelephone + " already exists");
221	        }
222	    }
223	
224	    /**
225	     * Canonicalizes the fields of a newly mapped owner on create, in place, so each value is
226	     * persisted and returned in its canonical form. The address is normalized (trimmed, whitespace
227	     * collapsed, upper-cased and common abbreviations expanded, rejecting a value blank after
228	     * normalization with 400), the telephone is normalized to E.164 (rejecting an unformattable
229	     * value with 400), the email is lower-cased, and a missing registration date defaults to the
230	     * server's current date. Canonicalising the address here, before the household checks read it,
231	     * ensures duplicate detection and the shared household id both compare the normalized form.
232	     * Centralising these per-field canonicalizations here keeps {@link #addOwner} focused on the
233	     * duplicate, household and customer-code rules.
234	     *
235	     * @param owner the newly mapped owner to canonicalize
236	     */
237	    private void normalizeOwnerFields(Owner owner) {
238	        // Normalize the address on create so it is stored and returned in canonical form and every
239	        // later comparison (household duplicate detection and the shared household id) uses it.
240	        // A value that is blank after normalization is rejected with 400.
241	        owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
242	        // Normalize the telephone on create so it is stored and returned in canonical E.164 form.
243	        // A value that cannot form a valid E.164 number is rejected with 400.
244	        owner.setTelephone(telephoneNormalizer.normalize(owner.getTelephone()));
245	        // Store the (already syntactically validated) email lower-cased so it is persisted and
246	        // returned in canonical form. A missing email is left untouched.
247	        owner.setEmail(normalizeEmail(owner.getEmail()));
248	        // Default the registration date to the server's current date when the client did not
249	        // supply one, then roll the effective date forward to a business day so a Saturday or
250	        // Sunday (whether supplied or defaulted) becomes the following Monday. The adjusted date
251	        // is persisted and returned in ISO 'YYYY-MM-DD' form and is the value every registration-
252	        // date-derived field (such as the membership number's year segment) and the per-day
253	        // create-limit are computed from.
254	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() == null
255	            ? java.time.LocalDate.now() : owner.getRegistrationDate();
256	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
257	    }
258	
259	    /**
260	     * Rolls a registration date forward to a business day: a Saturday or Sunday advances to the
261	     * following Monday, while a weekday is returned unchanged. Applied to the effective
262	     * registration date (whether supplied in the request or defaulted to the server date) so the
263	     * persisted registration date, every value derived from it and the per-day create-limit all
264	     * use the adjusted business day.
265	     *
266	     * @param date the effective registration date
267	     * @return the same date if it is a weekday, otherwise the following Monday
268	     */
269	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
270	        java.time.LocalDate adjusted = date;
271	        while (adjusted.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
272	            || adjusted.getDayOfWeek() == java.time.DayOfWeek.SUNDAY) {
273	            adjusted = adjusted.plusDays(1);
274	        }
275	        return adjusted;
276	    }
277	
278	    /**
279	     * Lower-cases the supplied email address so it is stored and returned in canonical form.
280	     * Bean validation on the request DTO has already guaranteed that any non-null value is a
281	     * syntactically valid address (rejecting anything else with 400).
282	     *
283	     * @param email the email value (may be {@code null})
284	     * @return the lower-cased email, or {@code null} if the input was {@code null}
285	     */
286	    private String normalizeEmail(String email) {
287	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
288	    }
289	
290	    /**
291	     * Builds the customer code '<CITY3>-<LAST3>-<NNNN>' for a newly created owner, where CITY3 is
292	     * the upper-cased first three letters of the city, LAST3 is the upper-cased first three letters
293	     * of the last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more than
294	     * the owners already in that city (e.g. 'LON-SMI-0007').
295	     *
296	     * @param city     the owner's city
297	     * @param lastName the owner's last name
298	     * @return the formatted customer code
299	     */
300	    private String nextCustomerCode(String city, String lastName) {
301	        String cityPrefix = city.substring(0, Math.min(3, city.length()))
302	            .toUpperCase(java.util.Locale.ROOT);
303	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length()))
304	            .toUpperCase(java.util.Locale.ROOT);
305	        int sequence = countOwnersInCity(city) + 1;
306	        return String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence);
307	    }
308	
309	    /**
310	     * Counts the existing owners located in the given city, compared case-insensitively. Used to
311	     * fix the per-city sequence of an owner's customer code at creation time.
312	     *
313	     * @param city the city of the owner being created
314	     * @return the number of existing owners in a matching city
315	     */
316	    private int countOwnersInCity(String city) {
317	        return (int) this.clinicService.findAllOwners().stream()
318	            .filter(existing -> existing.getCity() != null
319	                && existing.getCity().equalsIgnoreCase(city))
320	            .count();
321	    }
322	
323	    /**
324	     * Counts the existing owners whose registration date is the given adjusted business day. Used
325	     * to enforce the per-day cap that rejects creating an owner once {@link #MAX_OWNERS_PER_DAY}
326	     * owners already carry that business day as their registration date.
327	     *
328	     * @param date the adjusted business-day registration date to match
329	     * @return the number of existing owners registered on that date
330	     */
331	    private int countOwnersRegisteredOn(java.time.LocalDate date) {
332	        return (int) this.clinicService.findAllOwners().stream()
333	            .filter(existing -> date.equals(existing.getRegistrationDate()))
334	            .count();
335	    }
336	
337	    /**
338	     * Builds the membership number '<customerCode>-M<YY>' for a newly created owner, where YY is
339	     * the last two digits of the registration date's year (e.g. 'LON-SMI-0007-M26').
340	     *
341	     * @param customerCode     the owner's customer code
342	     * @param registrationDate the owner's registration date
343	     * @return the formatted membership number
344	     */
345	    private String membershipNumber(String customerCode, java.time.LocalDate registrationDate) {
346	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
347	    }
348	
349	    /**
350	     * Determines whether the given normalized telephone is already used by an existing owner.
351	     * Stored telephones are normalized to E.164 before comparison so values that differ only in
352	     * formatting (spaces, dashes, brackets) or in national vs. international notation are treated
353	     * as the same number.
354	     *
355	     * @param normalizedTelephone the normalized (E.164) telephone to look for
356	     * @return {@code true} if another owner already uses this telephone
357	     */
358	    private boolean isTelephoneInUse(String normalizedTelephone) {
359	        if (normalizedTelephone == null) {
360	            return false;
361	        }
362	        return this.clinicService.findAllOwners().stream()
363	            .map(Owner::getTelephone)
364	            .map(telephoneNormalizer::normalize)
365	            .anyMatch(normalizedTelephone::equals);
366	    }
367	
368	    /**
369	     * Returns the existing owners who share the given household, i.e. have the same last name and
370	     * the same address. The comparison delegates to {@link HouseholdNormalizer} so that values
371	     * differing only in letter case or in incidental whitespace are treated as the same household.
372	     *
373	     * @param lastName the last name of the owner being created
374	     * @param address  the address of the owner being created
375	     * @return the existing owners with a matching last name and address (possibly empty)
376	     */
377	    private List<Owner> sameHouseholdOwners(String lastName, String address) {
378	        String householdKey = householdNormalizer.householdKey(lastName, address);
379	        return this.clinicService.findAllOwners().stream()
380	            .filter(existing -> householdNormalizer
381	                .householdKey(existing.getLastName(), existing.getAddress()).equals(householdKey))
382	            .toList();
383	    }
384	
385	    /**
386	     * Counts the existing owners who share the given first and last name, compared
387	     * case-insensitively. Used to fix an owner's namesake count at creation time.
388	     *
389	     * @param firstName the first name of the owner being created
390	     * @param lastName  the last name of the owner being created
391	     * @return the number of existing owners with a matching first and last name
392	     */
393	    private int countNamesakes(String firstName, String lastName) {
394	        return (int) this.clinicService.findAllOwners().stream()
395	            .filter(existing -> existing.getFirstName() != null
396	                && existing.getFirstName().equalsIgnoreCase(firstName)
397	                && existing.getLastName() != null
398	                && existing.getLastName().equalsIgnoreCase(lastName))
399	            .count();
400	    }
401	
402	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
403	    @Override
404	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
405	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
406	        if (currentOwner == null) {
407	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
408	        }
409	        currentOwner.setAddress(ownerFieldsDto.getAddress());
410	        currentOwner.setCity(ownerFieldsDto.getCity());
411	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
412	        currentOwner.setLastName(ownerFieldsDto.getLastName());
413	        // Normalize the telephone to canonical E.164 form so it is stored and returned
414	        // consistently with create; an unformattable value is rejected with 400.
415	        currentOwner.setTelephone(telephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
416	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
417	        this.clinicService.saveOwner(currentOwner);
418	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
419	    }
420	
421	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
422	    @Transactional
423	    @Override
424	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
425	        Owner owner = this.clinicService.findOwnerById(ownerId);
426	        if (owner == null) {
427	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
428	        }
429	        this.clinicService.deleteOwner(owner);
430	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
431	    }
432	
433	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
434	    @Override
435	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
436	        Owner owner = this.clinicService.findOwnerById(ownerId);
437	        if (owner == null) {
438	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
439	        }
440	        HttpHeaders headers = new HttpHeaders();
441	        Pet pet = petMapper.toPet(petFieldsDto);
442	        owner.setId(ownerId);
443	        pet.setOwner(owner);
444	        pet.getType().setName(null);
445	        this.clinicService.savePet(pet);
446	        PetDto petDto = petMapper.toPetDto(pet);
447	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
448	            .buildAndExpand(pet.getId()).toUri());
449	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
450	    }
451	
452	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
453	    @Override
454	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
455	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
456	        if (currentOwner != null) {
457	            Pet currentPet = this.clinicService.findPetById(petId);
458	            if (currentPet != null) {
459	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
460	                currentPet.setName(petFieldsDto.getName());
461	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
462	                this.clinicService.savePet(currentPet);
463	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
464	            }
465	        }
466	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
467	    }
468	
469	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
470	    @Override
471	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
472	        HttpHeaders headers = new HttpHeaders();
473	        Visit visit = visitMapper.toVisit(visitFieldsDto);
474	        Pet pet = new Pet();
475	        pet.setId(petId);
476	        visit.setPet(pet);
477	        this.clinicService.saveVisit(visit);
478	        VisitDto visitDto = visitMapper.toVisitDto(visit);
479	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
480	            .buildAndExpand(visit.getId()).toUri());
481	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
482	    }
483	
484	
485	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
486	    @Override
487	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
488	        Owner owner = this.clinicService.findOwnerById(ownerId);
489	        if (owner != null) {
490	            Pet pet = owner.getPet(petId);
491	            if (pet != null) {
492	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
493	            }
494	        }
495	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
496	    }
497	}
